namespace Rhp::script::stubs {

// LuaLS annotations ("---@class", "---@param", ...) for editor autocomplete, generated by walking a
// lib type at compile time. Needs no Lua, so it also works with RHP_ENABLE=OFF.
//
//   std::ofstream f{"rhp_api.lua"};
//   f << stubs::rhp_api(role::kPatch) << stubs::generate<game_lib>(role::kPatch);
//
// A Rhp::convert<T> specialization names its Lua type with
//   static constexpr std::string_view lua_type = "vec3";
// and is annotated as `any` without it.
template <class T>
concept named_lua_type = requires {
    { Rhp::convert<T>::lua_type } -> std::convertible_to<std::string_view>;
};

namespace detail {

// A typed view's LuaLS type: rhp.span<number> for floating point elements, rhp.span<integer> else.
template <class E>
[[nodiscard]] std::string span_type_name() {
    return std::is_floating_point_v<E> ? "rhp.span<number>" : "rhp.span<integer>";
}

// The LuaLS type of a parameter or single result. Handles is the root lib's handles_of_t, so a
// handle declared in any sub-lib maps to its name.
template <utils::type_list_like Handles, class T>
[[nodiscard]] std::string type_name() {
    using U = std::remove_cvref_t<T>;
    if constexpr (script::detail::is_optional_v<U>) {
        return std::format("{}?", type_name<Handles, typename U::value_type>());
    } else if constexpr (script::detail::is_handle_v<Handles, U>) {
        return std::string{script::detail::find_handle_t<Handles, U>::name};
    } else if constexpr (script::detail::is_span_v<U>) {
        return span_type_name<std::remove_cv_t<typename U::element_type>>();
    } else if constexpr (script::detail::is_view_v<Handles, U>) {
        return std::string{script::detail::find_view_t<Handles, U>::name};
    } else if constexpr (std::is_pointer_v<U> && script::detail::is_view_v<Handles, std::remove_cv_t<std::remove_pointer_t<U>>>) {
        return std::format("{}?", script::detail::find_view_t<Handles, std::remove_cv_t<std::remove_pointer_t<U>>>::name); // nil when null
    } else if constexpr (std::same_as<U, bool>) {
        return "boolean";
    } else if constexpr (script::detail::lua_integer<U>) {
        return "integer";
    } else if constexpr (std::floating_point<U>) {
        return "number";
    } else if constexpr (script::detail::string_like<U>) {
        return "string";
    } else if constexpr (named_lua_type<U>) {
        return std::string{std::string_view{Rhp::convert<U>::lua_type}};
    } else {
        // Rhp::value and anything converted without a declared name.
        return "any";
    }
}

// One "---@return" per Lua result: tuples spread, Rhp::result<T> and Rhp::async<T> are T (errors
// are raised).
template <utils::type_list_like Handles, class R>
void append_returns(std::string& out) {
    using U = std::remove_cvref_t<R>;
    if constexpr (std::is_void_v<U>) {
        return;
    } else if constexpr (script::detail::is_tuple_v<U>) {
        [&]<class... Ts>(std::type_identity<std::tuple<Ts...>>) {
            ((out += std::format("---@return {}\n", type_name<Handles, Ts>())), ...);
        }(std::type_identity<U>{});
    } else if constexpr (is_result_v<U> || is_async_v<U>) {
        append_returns<Handles, typename U::value_type>(out);
    } else {
        out += std::format("---@return {}\n", type_name<Handles, U>());
    }
}

template <utils::type_list_like Handles, utils::type_list_like Args, std::size_t... Is>
void append_params([[maybe_unused]] std::string& out, std::index_sequence<Is...>) {
    ((out += std::format("---@param arg{} {}\n", Is + 1, type_name<Handles, utils::at_t<Args, Is>>())), ...);
}

[[nodiscard]] inline std::string arg_list(std::size_t arity) {
    std::string out;
    for (std::size_t i = 1; i <= arity; ++i) {
        out += std::format("{}arg{}", i > 1 ? ", " : "", i);
    }
    return out;
}

// The LuaLS type of a method's results: "" (none), "integer", "integer, string".
template <utils::type_list_like Handles, class R>
[[nodiscard]] std::string result_types() {
    using U = std::remove_cvref_t<R>;
    if constexpr (std::is_void_v<U>) {
        return {};
    } else if constexpr (script::detail::is_tuple_v<U>) {
        return [&]<class... Ts>(std::type_identity<std::tuple<Ts...>>) {
            std::string out;
            ((out += (out.empty() ? "" : ", ") + type_name<Handles, Ts>()), ...);
            return out;
        }(std::type_identity<U>{});
    } else if constexpr (is_result_v<U> || is_async_v<U>) {
        return result_types<Handles, typename U::value_type>();
    } else {
        return type_name<Handles, U>();
    }
}

// "fun(self: entity, arg1: number): vec2" for a method ("async fun(...)" when it waits).
template <utils::type_list_like Handles, class M, std::size_t... Is>
[[nodiscard]] std::string method_type(std::string_view self, std::index_sequence<Is...>) {
    using args = typename M::traits::args;
    std::string out = std::format("{}fun(self: {}", M::is_async ? "async " : "", self);
    ((out += std::format(", arg{}: {}", Is + 1, type_name<Handles, utils::at_t<args, Is + 1>>())), ...);
    out += ')';
    if (const std::string results = result_types<Handles, typename M::traits::return_type>(); !results.empty()) {
        out += ": " + results;
    }
    return out;
}

// One class per handle, with the methods and properties the caller may use.
template <utils::type_list_like Handles, class H, class... Ms>
void append_handle_class(std::string& out, role caller, utils::type_list<Ms...>) {
    out += std::format("---@class {}\n", H::name);
    const auto member = [&]<class M>(std::type_identity<M>) {
        if constexpr (std::is_same_v<typename M::self_type, typename H::type>) {
            if (!allows(caller, M::required)) {
                return;
            }
            if constexpr (M::kind == script::detail::entry_kind::kProperty) {
                out += std::format("---@field {} {} read-only\n", M::name, result_types<Handles, typename M::traits::return_type>());
            } else {
                out += std::format("---@field {} {}\n", M::name,
                                   method_type<Handles, M>(H::name, std::make_index_sequence<M::traits::arity - 1>{}));
            }
        }
    };
    (member(std::type_identity<Ms>{}), ...);
    out += '\n';
}

// " [0, 10] m/s: what it is for" from a variable's or field's tags (empty without any).
template <class Meta>
[[nodiscard]] std::string described() {
    std::string out;
    if constexpr (Meta::has_range) {
        out += std::format(" [{}, {}]", *Meta::lower(), *Meta::upper());
    }
    if (!Meta::unit().empty()) {
        out += std::format(" {}", Meta::unit());
    }
    if (!Meta::doc().empty()) {
        std::string doc{Meta::doc()};
        for (char& c : doc) {
            c = c == '\n' || c == '\r' ? ' ' : c; // one annotation line
        }
        out += std::format("{} {}", out.empty() ? "" : ":", doc);
    }
    return out;
}

// The LuaLS type of a view type's field: its value, a span for an array, the nested view's name.
template <utils::type_list_like Handles, class F>
[[nodiscard]] std::string field_type() {
    using M = typename F::value_type;
    if constexpr (F::shape == 2) {
        return span_type_name<typename script::detail::array_traits<M>::element>();
    } else if constexpr (F::shape == 3) {
        return type_name<Handles, M>();
    } else if constexpr (std::is_enum_v<M>) {
        return "integer";
    } else {
        return type_name<Handles, M>();
    }
}

// One class per view type, with its fields: writable ones (for a caller with kPatch) are plain,
// the rest read-only; an array or struct field is read-only itself (its elements or fields aren't).
template <utils::type_list_like Handles, class V, class... Fs>
void append_view_class(std::string& out, role caller, utils::type_list<Fs...>) {
    out += std::format("---@class {}\n", V::name);
    const auto field = [&]<class F>(std::type_identity<F>) {
        if constexpr (std::is_same_v<typename F::owner_type, typename V::type>) {
            const bool writable = F::shape == 1 && F::writable && allows(caller, role::kPatch);
            out += std::format("---@field {} {}{}{}\n", F::name, field_type<Handles, F>(), writable ? "" : " read-only", described<typename F::meta>());
        }
    };
    (field(std::type_identity<Fs>{}), ...);
    out += '\n';
}

template <utils::type_list_like Handles, class Members, class Fields, class... Hs>
void append_handle_classes([[maybe_unused]] std::string& out, [[maybe_unused]] role caller, utils::type_list<Hs...>) {
    const auto one = [&]<class H>(std::type_identity<H>) {
        if constexpr (H::kind == script::detail::entry_kind::kHandle) {
            append_handle_class<Handles, H>(out, caller, Members{});
        } else {
            append_view_class<Handles, H>(out, caller, Fields{});
        }
    };
    (one(std::type_identity<Hs>{}), ...);
}

template <utils::type_list_like Handles, class Lib>
struct lib_writer;

// Emits one lib: its class with fields, its table, its functions, then its sub-libs (recursively).
// `path` is the dotted Lua path ("game", "game.debug").
template <utils::type_list_like Handles, utils::fixed_string Name, class... Entries>
struct lib_writer<Handles, lib<Name, Entries...>> {
    static void append(std::string& out, std::string_view path, role caller) {
        out += std::format("---@class {}\n", path);
        (field<Entries>(out, path, caller), ...);
        out += std::format("{} = {{}}\n\n", path);
        (function<Entries>(out, path, caller), ...);
        (sub<Entries>(out, path, caller), ...);
    }

private:
    template <class Entry>
    static void field(std::string& out, std::string_view path, role caller) {
        using script::detail::entry_kind;
        if constexpr (Entry::kind == entry_kind::kVar) {
            // Writes need kPatch; below that the variable is effectively read-only.
            const std::string_view suffix = allows(caller, role::kPatch) ? "" : " read-only";
            out += std::format("---@field {} {}{}{}\n", Entry::name, type_name<Handles, typename Entry::value_type>(), suffix, described<typename Entry::meta>());
        } else if constexpr (Entry::kind == entry_kind::kRo) {
            out += std::format("---@field {} {} read-only{}\n", Entry::name, type_name<Handles, typename Entry::value_type>(), described<typename Entry::meta>());
        } else if constexpr (Entry::kind == entry_kind::kSub) {
            out += std::format("---@field {} {}.{}\n", Entry::name, path, Entry::name);
        }
    }

    template <class Entry>
    static void function(std::string& out, std::string_view path, role caller) {
        if constexpr (Entry::kind == script::detail::entry_kind::kFn) {
            if (!allows(caller, Entry::required)) {
                return;
            }
            using traits = typename Entry::traits;
            if constexpr (Entry::is_async) {
                out += "---@async\n"; // the call suspends the script until the result arrives
            }
            append_params<Handles, typename traits::args>(out, std::make_index_sequence<traits::arity>{});
            append_returns<Handles, typename traits::return_type>(out);
            out += std::format("function {}.{}({}) end\n\n", path, Entry::name, arg_list(traits::arity));
        }
    }

    template <class Entry>
    static void sub(std::string& out, std::string_view path, role caller) {
        if constexpr (Entry::kind == script::detail::entry_kind::kSub) {
            lib_writer<Handles, typename Entry::lib>::append(out, std::format("{}.{}", path, Entry::name), caller);
        }
    }
};

// Every block ends with a blank line; the file ends with exactly one newline.
inline void trim_trailing_blank(std::string& out) {
    while (out.size() >= 2 && out.ends_with("\n\n")) {
        out.pop_back();
    }
}

} // namespace detail

// LuaLS annotations for one lib (and its sub-libs), filtered for a caller role: functions the
// caller can't call are left out, variables it can't write are marked read-only. No "---@meta";
// concatenate rhp_api() and any number of generate<L>() into one file.
template <lib_type L>
[[nodiscard]] std::string generate(role caller = role::kAdmin) {
    using handles = script::detail::handles_of_t<L>;
    std::string out;
    detail::append_handle_classes<handles, script::detail::members_of_t<L>, script::detail::fields_in_t<L>>(out, caller, handles{});
    detail::lib_writer<handles, L>::append(out, L::name, caller);
    detail::trim_trailing_blank(out);
    return out;
}

template <lib_type L>
void write(std::ostream& out, role caller = role::kAdmin) {
    out << generate<L>(caller);
}

// The `rhp` global, `require` and the module-hook class, filtered for a caller role. Starts with
// "---@meta".
[[nodiscard]] inline std::string rhp_api(role caller = role::kAdmin) {
    std::string out = R"lua(---@meta

---@class rhp
---@field role string "observe", "patch" or "admin"
rhp = {}

)lua";
    if (allows(caller, role::kPatch)) {
        out += R"lua(---Overrides a C++ patch point until this module is reverted.
---@param id string
---@param handler fun(original: function, ...): any
function rhp.patch(id, handler) end

)lua";
    }
    out += R"lua(---Suspends this script for `frames` pump() calls (at least 1).
---@param frames integer
function rhp.wait(frames) end

---Suspends this script until the next pump().
function rhp.next_frame() end

---Suspends this script for at least `ms` milliseconds.
---@param ms number
function rhp.sleep(ms) end

---Calls `fn` after `ms` milliseconds (every `ms` if `repeating`). Removed when this module is reverted.
---@param ms number
---@param fn fun()
---@param repeating? boolean
---@return integer id
function rhp.timer(ms, fn, repeating) end

---Calls `fn` once after `ms` milliseconds. Removed when this module is reverted.
---@param ms number
---@param fn fun()
---@param opts? rhp.handler_options
---@return integer id
function rhp.after(ms, fn, opts) end

---Calls `fn` every `ms` milliseconds, at most once per pump(); `opts.times` limits the calls.
---@param ms number
---@param fn fun()
---@param opts? rhp.handler_options
---@return integer id
function rhp.every(ms, fn, opts) end

---Calls `fn` every pump(), starting with the next one. Removed when this module is reverted.
---@param fn fun()
---@param opts? rhp.handler_options
---@return integer id
function rhp.every_frame(fn, opts) end

---Calls `fn` every `frames` pump() calls (the first `frames` pumps from now).
---@param frames integer
---@param fn fun()
---@param opts? rhp.handler_options
---@return integer id
function rhp.every_frames(frames, fn, opts) end

---Stops a timer, frame callback or subscription of this module from firing until rhp.resume(id).
---@param id integer
function rhp.pause(id) end

---Lets a paused timer, frame callback or subscription fire again (timers keep their remaining time).
---@param id integer
function rhp.resume(id) end

---Sets a timer's interval (milliseconds) or a frame callback's period (frames) and restarts its countdown.
---@param id integer
---@param interval number
function rhp.reschedule(id, interval) end

---This module's timers and frame callbacks.
---@return rhp.schedule_info[]
function rhp.timers() end

---Calls `handler` each time the event fires: a C++ event of that name, else an rhp.publish of this identity. Removed when this module is reverted.
---@param event string
---@param handler fun(...)
---@param opts? rhp.handler_options
---@return integer id
function rhp.on(event, handler, opts) end

---Like rhp.on, removed after the first delivery.
---@param event string
---@param handler fun(...)
---@param opts? rhp.handler_options
---@return integer id
function rhp.once(event, handler, opts) end

---Calls `handler` with a table describing each failed timer, frame callback, event handler or task of this identity.
---@param handler fun(failure: rhp.handler_failure)
---@param opts? rhp.handler_options
---@return integer id
function rhp.on_error(handler, opts) end

---Removes a timer, frame callback or subscription, or cancels a task, made by this module.
---@param id integer
function rhp.off(id) end

---Delivers an event to every rhp.on / rhp.once / rhp.wait_event of this identity at the next pump(). Values are copied (no functions or userdata). Returns false if the event queue was full.
---@param event string
---@param ... any
---@return boolean queued
function rhp.publish(event, ...) end

---Suspends this script until `event` fires (a C++ event or an rhp.publish); returns true and its arguments, or false, "timeout" after `timeout_ms`.
---@param event string
---@param timeout_ms? number
---@return boolean fired
---@return any ...
function rhp.wait_event(event, timeout_ms) end

---Runs `fn(...)` as a background task of this module, starting at the next pump(). Cancelled when this module is reverted.
---@param fn fun(...): ...
---@param ... any
---@return rhp.task
function rhp.spawn(fn, ...) end

---This module's tasks that have not finished.
---@return rhp.task[]
function rhp.tasks() end

---Queue and handler counters of this identity's sandbox.
---@return rhp.stats
function rhp.stats() end

---The variables the installed libs expose, with their values and tags (all, or those under `prefix`).
---@param prefix? string a lib or a path ("game", "game.speed")
---@return rhp.tunable[]
function rhp.tunables(prefix) end

---Everything this identity can use: the installed libs, C++ events and patch points, described as tables.
---@return table
function rhp.api() end

---Streams a value to the host while the script keeps running.
---@param value any
function rhp.emit(value) end

---Byte buffers this script owns (never journaled: script state, like a table).
---@class rhp.buffer_lib
rhp.buffer = {}

---A buffer of `size` bytes, each `fill` (default 0).
---@param size integer
---@param fill? integer
---@return rhp.buffer
function rhp.buffer.new(size, fill) end

---A buffer holding a copy of a string's, a buffer's or a span's bytes.
---@param bytes string|rhp.buffer|rhp.span<number>|rhp.span<integer>
---@return rhp.buffer
function rhp.buffer.from(bytes) end

---Elements of C++ memory (or of a buffer), read and written in place: v[i] (1-based, bounds-checked), #v, pairs(v). Writes to C++ memory need the patch role and are undone with the module.
---@class rhp.span<T>: { [integer]: T }
---@operator len: integer
local span = {}

---@param i integer
---@return T
function span:get(i) end

---@param i integer
---@param value T
function span:set(i, value) end

---Elements i..j (default: to the end) sharing the memory.
---@param i integer
---@param j? integer
---@return rhp.span<T>
function span:slice(i, j) end

---Sets elements i..j (default: all) to `value`.
---@param value T
---@param i? integer
---@param j? integer
function span:fill(value, i, j) end

---Copies a span's, a buffer's or a table's elements here, from element `pos` (default 1).
---@param source rhp.span<number>|rhp.span<integer>|rhp.buffer|T[]
---@param pos? integer
function span:copy(source, pos) end

---Elements i..j (default: all) as a new table.
---@param i? integer
---@param j? integer
---@return T[]
function span:totable(i, j) end

---The element type: "f32", "u8", "i64", ...
---@return string
function span:kind() end

---Whether elements may be set.
---@return boolean
function span:writable() end

---Bytes a script owns: b[i] is a byte (1-based); numbers of every width at a byte position, little ("le", default) or big ("be") endian.
---@class rhp.buffer: rhp.span<integer>
local buffer = {}

---Bytes i..j (default: to the end) sharing the memory.
---@param i integer
---@param j? integer
---@return rhp.buffer
function buffer:slice(i, j) end

---A typed view of the bytes from `pos` (default 1): `count` elements (default: as many as fit) of "i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "f32", "f64" or "byte".
---@param kind string
---@param pos? integer
---@param count? integer
---@return rhp.span<number>|rhp.span<integer>
function buffer:view(kind, pos, count) end

---Bytes i..j (default: all) as a string.
---@param i? integer
---@param j? integer
---@return string
function buffer:tostring(i, j) end

---@param pos integer
---@param len integer
---@return string
function buffer:read_string(pos, len) end

---@param pos integer
---@param s string
---@return integer next
function buffer:write_string(pos, s) end

---string.pack(fmt, ...) written at `pos`.
---@param pos integer
---@param fmt string
---@param ... any
---@return integer next
function buffer:pack(pos, fmt, ...) end

---string.unpack(fmt, ...) of the bytes from `pos`: the values, then the position after them.
---@param pos integer
---@param fmt string
---@return any ...
function buffer:unpack(pos, fmt) end

)lua";
    for (const std::string_view kind : {"i8", "u8", "i16", "u16", "i32", "u32", "i64", "u64", "f32", "f64"}) {
        const std::string_view type = kind.front() == 'f' ? "number" : "integer";
        out += std::format("---@param pos integer\n---@param order? \"le\"|\"be\"\n---@return {}\nfunction buffer:read_{}(pos, order) end\n\n", type, kind);
        out += std::format("---@param pos integer\n---@param value {}\n---@param order? \"le\"|\"be\"\n---@return integer next\nfunction buffer:write_{}(pos, value, order) end\n\n",
                           type, kind);
    }
    out += R"lua(---Number of pump() calls so far.
---@return integer
function rhp.frame() end

---A loaded module of this identity (read-only, always its current revision).
---@param name string
---@return table
function require(name) end

---@class rhp.handler_options
---@field times? integer calls before it removes itself (rhp.every and frame callbacks only)
---@field priority? integer higher runs first (rhp.on, rhp.once, rhp.on_error only); ties keep subscription order
---@field on_error? "report"|"remove"|"fault" what a failing call does (default: the sandbox's policy)

---@class rhp.schedule_info
---@field id integer
---@field kind "timer"|"frames"
---@field interval number milliseconds, or frames
---@field remaining number milliseconds, or frames
---@field runs integer
---@field times? integer
---@field repeating boolean
---@field paused boolean
---@field running boolean

---@class rhp.task
---@field id integer
---@field status fun(self: rhp.task): "suspended"|"running"|"done"|"failed"|"cancelled"
---@field cancel fun(self: rhp.task): boolean
---@field join fun(self: rhp.task): ...

---@class rhp.handler_failure
---@field module string
---@field kind "timer"|"frame"|"event"|"task"
---@field source string
---@field id integer
---@field action "report"|"remove"|"fault"
---@field code string
---@field message string
---@field where string
---@field traceback string

---@class rhp.tunable
---@field path string
---@field type string
---@field value any
---@field writable boolean
---@field min? number
---@field max? number
---@field step? number
---@field unit? string
---@field doc? string

---@class rhp.stats
---@field dropped_events integer
---@field queued_events integer
---@field timers integer
---@field subscriptions integer
---@field tasks integer
---@field waiting integer
---@field async_waiting integer
---@field async_compensated integer
---@field async_dropped integer
---@field handler_failures integer
---@field memory integer

---@class rhp.module
---@field on_load? fun()
---@field on_unload? fun()
---@field on_save? fun(): any
---@field on_restore? fun(state: any)
)lua";
    return out;
}

} // namespace Rhp::script::stubs
